const item = items[0].json || {};

const msg = String(
  item.message_text ||
  item.property_last_whats_app_message ||
  item.property_last_whatsapp_message ||
  ''
).trim();

let reply = '';
let selected_service_path = '';
let advisor_step = 'Main Menu';
let whatsapp_stage = 'Menu Sent';

if (msg === '1') {
  selected_service_path = 'Company Setup';
  advisor_step = 'Investor Type';
  whatsapp_stage = 'Qualification';

  reply = `مرحباً، لتحديد مسار تأسيس الشركة المناسب، اختر نوع المستثمر:

1️⃣ سعودي / مقيم
2️⃣ مستثمر أجنبي

يرجى الرد برقم الخيار فقط.`;
} else if (msg === '2') {
  selected_service_path = 'HR & Recruitment';
  advisor_step = 'HR Need Type';
  whatsapp_stage = 'Qualification';

  reply = `اختر نوع خدمة الموارد البشرية:

1️⃣ توظيف
2️⃣ تشغيل
3️⃣ استقدام
4️⃣ استشارة موارد بشرية

يرجى الرد برقم الخيار فقط.`;
} else if (msg === '3') {
  selected_service_path = 'GRO';
  advisor_step = 'GRO Service Type';
  whatsapp_stage = 'Qualification';

  reply = `اختر خدمة العلاقات الحكومية:

1️⃣ قوى
2️⃣ مدد
3️⃣ التأمينات
4️⃣ مقيم
5️⃣ بلدي والزكاة والضريبة

يرجى الرد برقم الخيار فقط.`;
} else if (msg === '4') {
  selected_service_path = 'Premium Residency';
  advisor_step = 'Premium Residency Type';
  whatsapp_stage = 'Qualification';

  reply = `اختر نوع الإقامة المميزة:

1️⃣ إقامة مميزة عادية
2️⃣ إقامة مستثمر
3️⃣ إقامة رائد أعمال
4️⃣ غير متأكد

يرجى الرد برقم الخيار فقط.`;
} else {
  reply = `أهلاً بك في بزنس بارتنر سولوشنز 👋

نحن شركة سعودية متخصصة في خدمات الأعمال للشركات والمستثمرين: تأسيس الشركات السعودية والأجنبية، تراخيص الاستثمار، الإقامة المميزة، الموارد البشرية والتشغيل، والعلاقات الحكومية والاستشارات.

اختر رقم الخدمة التي تهمك:

1️⃣ تأسيس الشركات
2️⃣ حلول الموارد البشرية
3️⃣ العلاقات الحكومية
4️⃣ الإقامة المميزة`;
}

return [
  {
    json: {
      ...item,
      selected_service_path,
      advisor_step,
      whatsapp_stage,
      text_body: reply,
      reply_text: reply,
      output: reply,
      send_ready: true,
    },
  },
];

const OWNER_PHONE = "966530540231";

function value(v, fallback = "") {
  if (v === undefined || v === null) return fallback;
  if (Array.isArray(v)) {
    if (v.length === 0) return fallback;
    return v.filter(x => x !== null && x !== undefined && x !== "").join(", ");
  }
  return String(v).trim();
}

function cut(text, max = 220) {
  const t = value(text);
  if (t.length <= max) return t;
  return t.slice(0, max) + "...";
}

const output = [];

for (const item of $input.all()) {
  const j = item.json || {};

  const clientName = value(
    j.name ||
    j.client_name ||
    "WhatsApp Client"
  );

  const clientPhone = value(
    j.property_whats_app ||
    j.property_whatsapp ||
    j.phone ||
    j.recipient_phone ||
    ""
  );

  const service = value(
    j.property_selected_service_path ||
    j.selected_service_path ||
    j.detected_service ||
    "Not Defined"
  );

  const stage = value(
    j.property_whats_app_stage ||
    j.property_whatsapp_stage ||
    j.whatsapp_stage ||
    "Not Defined"
  );

  const step = value(
    j.property_advisor_step ||
    j.advisor_step ||
    "Not Defined"
  );

  const lastMessage = value(
    j.message_text ||
    j.property_last_whats_app_message ||
    j.normalized_text ||
    "No message"
  );

  const crmUrl = value(
    j.url ||
    j.crm_url ||
    "No CRM link"
  );

  const notificationText =
`🔔 WhatsApp Lead

Client: ${clientName}
Phone: ${clientPhone}

Service: ${service}
Stage: ${stage}
Step: ${step}

Message:
${cut(lastMessage, 220)}

CRM:
${crmUrl}`;

  output.push({
    json: {
      ...j,

      owner_notification_ready: true,
      owner_phone: OWNER_PHONE,
      recipient_phone: OWNER_PHONE,

      owner_notification_text: notificationText,
      text_body: notificationText,
      reply_text: notificationText,
      output: notificationText,

      send_ready: true
    }
  });
}

return output;
